/** Native design and flow regression. All television/version values below are explicitly synthetic. */
public class Version011UiChecks extends AerialUiChecks {
 float expectedFont;int expectedWidth;
 public void onCreate(Bundle args){if(args!=null){expectedFont=Float.parseFloat(args.getString("fontScaleExpected","0"));expectedWidth=Integer.parseInt(args.getString("widthExpected","0"));}super.onCreate(args);}
 void settlePage()throws Exception{long end=System.currentTimeMillis()+15000;boolean settled=false;while(System.currentTimeMillis()<end){ViewGroup body=(ViewGroup)field("body");settled=body.isLaidOut()&&!body.isLayoutRequested()&&body.getAlpha()==1f&&body.getTranslationY()==0f&&(body.getAnimation()==null||body.getAnimation().hasEnded());for(int i=0;i<body.getChildCount();i++){View child=body.getChildAt(i);if(child.getVisibility()==View.VISIBLE&&child.getAlpha()!=1f)settled=false;}if(settled)break;Thread.sleep(100);}if(!settled)throw new AssertionError("Page transition did not settle visibly");getUiAutomation().waitForIdle(300,10000);}
 boolean remotePainted()throws Exception{View ok=find(activity.getWindow().getDecorView(),"确定");Rect bounds=new Rect();if(ok==null||!ok.getGlobalVisibleRect(bounds)||bounds.isEmpty())return false;android.graphics.Bitmap rendered=getUiAutomation().takeScreenshot();int pixels=0;for(int y=Math.max(0,bounds.top);y<Math.min(rendered.getHeight(),bounds.bottom);y+=4)for(int x=Math.max(0,bounds.left);x<Math.min(rendered.getWidth(),bounds.right);x+=4){int color=rendered.getPixel(x,y);if(android.graphics.Color.green(color)>90&&android.graphics.Color.green(color)>android.graphics.Color.red(color)+20)pixels++;}rendered.recycle();return pixels>20;}
 @Override void shot(String name)throws Exception{Thread.sleep(1500);getUiAutomation().waitForIdle(300,10000);super.shot(name);}
 void closeSheet()throws Exception{dialogTap("知道了");Thread.sleep(300);}
 public void onStart(){Bundle result=new Bundle();try{
  getTargetContext().getSharedPreferences("linkdeck",0).edit().putBoolean("resume_connection",false).putBoolean("largeRemote",false).putBoolean("reduce_motion",false).commit();
  activity=startActivitySync(new Intent().setClassName("cn.linkdeck.adb","cn.linkdeck.adb.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));Thread.sleep(1500);
  if(expectedFont>0)check(Math.abs(activity.getResources().getConfiguration().fontScale-expectedFont)<.03,"requested large font is actually applied");
  if(expectedWidth>0){android.graphics.Bitmap screen=getUiAutomation().takeScreenshot();check(activity.getResources().getDisplayMetrics().widthPixels==expectedWidth&&screen.getWidth()==expectedWidth,"physical display, resource width and screenshot agree");screen.recycle();}
  check(((Integer)field("BG"))==0xff0b131e&&((Integer)field("INK"))==0xffedf5ff,"native dark palette and readable foreground active");
  check(find(activity.getWindow().getDecorView(),"安装应用")!=null&&find(activity.getWindow().getDecorView(),"文件传输")!=null,"offline dashboard retains real app and file entry points");
  View update=find(activity.getWindow().getDecorView(),"检查更新");check(update.getTop()>=0&&update.getBottom()<=((View)update.getParent()).getHeight(),"paired action fits inside its row without clipping rounded corners");
  check(!dialogHas("本机已验证")&&!dialogHas("已连接"),"offline UI does not fabricate connection or stability evidence");shot("v011-home-offline");
  tap("安装应用");waitFor("installation chooser retains phone app and APK routes",()->dialogHas("选择手机已安装应用")&&dialogHas("选择 APK 文件"));shot("v011-install-chooser");dialogTap("取消");
  call("show",new Class[]{int.class},1);Thread.sleep(700);check(find(activity.getWindow().getDecorView(),"确定")!=null&&find(activity.getWindow().getDecorView(),"主页")!=null&&find(activity.getWindow().getDecorView(),"发送到设备")!=null,"circular remote keeps direction, HOME and text entry");settlePage();View menu=find(activity.getWindow().getDecorView(),"菜单");View menuParent=(View)menu.getParent();check(menu.getBottom()<=menuParent.getHeight()-menuParent.getPaddingBottom(),"round remote action keeps its caption inside padding at current font scale");waitFor("remote OK artwork is actually rendered on the physical screenshot",()->remotePainted());shot("v011-remote-offline");if(expectedFont>0){View slider=(View)field("volumeGlide");runOnMainSync(()->slider.requestRectangleOnScreen(new Rect(0,0,slider.getWidth(),slider.getHeight()),true));waitFor("small-screen volume slider can scroll fully into the viewport",()->{Rect visible=new Rect();return slider.getGlobalVisibleRect(visible)&&visible.height()>=slider.getHeight()-2&&visible.width()>=slider.getWidth()-2;});float density=activity.getResources().getDisplayMetrics().density;View less=find(activity.getWindow().getDecorView(),"音量 −"),more=find(activity.getWindow().getDecorView(),"音量 ＋");Rect left=new Rect(),right=new Rect();check(slider.getWidth()>=80*density&&less.getGlobalVisibleRect(left)&&more.getGlobalVisibleRect(right)&&left.height()>=40*density&&right.height()>=40*density,"small-screen slider and speaker controls retain usable touch bounds");shot("v012-volume-small");}tap("键盘输入");check(find(activity.getWindow().getDecorView(),"发送到设备").isShown(),"keyboard shortcut reveals the real text input panel");tap("键盘输入");check(!find(activity.getWindow().getDecorView(),"发送到设备").isShown(),"keyboard panel can collapse without leaving remote");
  tap("确定");waitFor("offline remote remains connection-gated",()->dialogHas("连接后即可操作"));Rect bounds=new Rect();getUiAutomation().getRootInActiveWindow().getBoundsInScreen(bounds);check(bounds.bottom>activity.getResources().getDisplayMetrics().heightPixels*.7,"connection sheet anchors near bottom");shot("v011-connect-sheet");dialogTap("继续浏览");
  call("show",new Class[]{int.class},2);Thread.sleep(600);check(find(activity.getWindow().getDecorView(),"安装 APK")!=null&&find(activity.getWindow().getDecorView(),"选择手机应用")!=null,"applications page keeps local installation actions");shot("v011-apps-offline");
  call("show",new Class[]{int.class},3);Thread.sleep(600);check(find(activity.getWindow().getDecorView(),"上传文件")!=null,"file page keeps upload handler");shot("v011-files-offline");
  call("show",new Class[]{int.class},4);Thread.sleep(600);check(find(activity.getWindow().getDecorView(),"执行命令")!=null&&find(activity.getWindow().getDecorView(),"上次执行结果")!=null,"tools keep command execution and complete result history");shot("v011-tools-offline");
  call("dialog",new Class[]{String.class,String.class},"测试错误详情","仅用于界面验证，未连接电视。\n失败阶段：读取电视信息\n命令：pm list packages\n退出码：1\n\n完整返回：\n（电视未返回文本）");Thread.sleep(600);check(dialogHas("pm list packages")&&dialogHas("复制"),"redesigned sheet retains full command error and copy action");shot("v011-error-sheet");closeSheet();
  call("show",new Class[]{int.class},2);Thread.sleep(300);File jf=asset("aerial-release.json"),apk=asset("aerial-standard.apk");AerialDownload.Asset source=AerialDownload.metadata(read(jf),"standard");Object plan=plan(apk,source,22);Class<?> pc=plan.getClass();call("validateAerialArchive",new Class[]{pc},plan);put(plan,"model","测试电视 · 仅界面预览");call("showAerialPlan",new Class[]{pc},plan);Thread.sleep(650);
  check(dialogHas("安装前确认")&&dialogHas("本机待验证"),"install sheet separates requirements from local stability");
  check(dialogHas("仍需实测")&&dialogHas("首次安装"),"first-install sheet does not invent a matching installed signature");Rect cancelBounds=new Rect();for(android.view.accessibility.AccessibilityNodeInfo node:getUiAutomation().getRootInActiveWindow().findAccessibilityNodeInfosByText("取消")){node.getBoundsInScreen(cancelBounds);if(cancelBounds.height()>0)break;}android.graphics.Bitmap viewport=getUiAutomation().takeScreenshot();check(cancelBounds.height()>0&&cancelBounds.bottom<=viewport.getHeight()&&cancelBounds.right<=viewport.getWidth(),"cancel action stays within the physical viewport");viewport.recycle();shot("v011-aerial-sheet");dialogTap("查看检查详情  ﹀");waitFor("full installation evidence remains expandable",()->dialogHas("不保证主页键"));dialogTap("取消");waitFor("sheet cancel cleans prepared APK",()->!apk.exists());jf.delete();
  call("show",new Class[]{int.class},0);Thread.sleep(600);tap("版本管理与故障采集  ﹀");check(find(activity.getWindow().getDecorView(),"本机稳定版本").getVisibility()==View.VISIBLE,"expanded management keeps stable version and diagnosis tools");
  call("appearance",new Class[]{});waitFor("motion settings sheet is accessible",()->dialogHas("界面设置")&&dialogHas("减少动态效果"));android.view.accessibility.AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();boolean toggled=false;for(android.view.accessibility.AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText("减少动态效果")){if(node.isCheckable()&&node.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK)){toggled=true;break;}}check(toggled,"native switch remains an accessible toggle");Thread.sleep(200);check(getTargetContext().getSharedPreferences("linkdeck",0).getBoolean("reduce_motion",false),"reduce-motion preference can be enabled from the native settings sheet");dialogTap("关闭");call("show",new Class[]{int.class},1);check(((View)field("body")).getAlpha()==1f&&((View)field("body")).getTranslationY()==0,"reduced-motion navigation settles without transition");getTargetContext().getSharedPreferences("linkdeck",0).edit().putBoolean("reduce_motion",false).commit();
  result.putString("stream","VERSION 011 NATIVE UI PASSED: "+passes+" checks.\n");finish(-1,result);
 }catch(Throwable t){result.putString("stream",android.util.Log.getStackTraceString(t));finish(0,result);}}
}
